def fragment_ptr(schema: dict, current: str) -> str:
    if not isinstance(schema, dict):
        return current
    ref = schema.get("$ref")
    extra = set(schema.keys()) - {"$ref", "$id", "$schema", "description"}
    if isinstance(ref, str) and "#" in ref and not extra:
